    vocabulary: [["Temporal","(Adjective) Relating to time."],["Throughput","(Noun) Volume processed in a given period."],["Truncated","(Adjective) Cut short; incomplete."],["Staffing ratio","(Noun) Number of staff relative to people served."],["Respite","(Noun) Rest period for caregivers."],["Continuity","(Noun) Ongoing relationship over time without breaks."],["Assembly-line","(Noun) Mass production system (figurative: impersonal speed)."],["Bottleneck","(Noun) A point that limits overall flow."],["Philanthropy","(Noun) Charitable giving, often organised."],["Margin","(Noun) Extra time or resources beyond minimum need."],["Burnout","(Noun) Exhaustion from prolonged stress."],["Relational","(Adjective) Based on relationship rather than transaction."],["Moralising","(Verb) Treating problems as moral failures of individuals."],["Duration","(Noun) Length of time something continues."],["Sandwich generation","(Noun) Adults caring for children and ageing parents simultaneously."],["Ticked","(Adjective) Marked complete on a form (figurative)."]],
