    vocabulary: [["Mortality","(Noun) Death rate in a population."],["Patent","(Noun) Legal exclusive right to make or sell an invention."],["Ableism","(Noun) Discrimination favouring non-disabled people."],["Rollout","(Noun) Process of introducing something widely."],["Gene therapy","(Noun) Treatment modifying genes to fight disease."],["Telehealth","(Noun) Remote healthcare via technology."],["Solidarity","(Noun) Mutual support among groups with shared aims."],["Intellectual property","(Noun) Legal rights over creations of the mind."],["Equity","(Noun) Fairness in outcomes and access."],["Marginal","(Adjective) On the edge of importance or inclusion."],["Bolting on","(Phrase) Adding as an afterthought."],["Preventable","(Adjective) Able to be avoided with proper care."],["Advocacy","(Noun) Public support for a cause or group."],["Inaccessible","(Adjective) Not reachable or usable by all."],["Breakthrough","(Noun) An important sudden advance."],["Postcode","(Noun) Postal code area (figurative: neighbourhood identity)."]],
