    vocabulary: [["Sacrifice","(Noun) Giving up something valued for another’s good."],["Myth","(Noun) A widely held but oversimplified or false belief."],["Self-erasure","(Noun) Disappearing one’s own needs and identity."],["Respite","(Noun) Short rest from caregiving duties."],["Exploitation","(Noun) Unfair use of someone’s labour or vulnerability."],["Stigma","(Noun) Mark of disgrace associated with a condition or role."],["Internalise","(Verb) To make external expectations part of oneself."],["Indictment","(Noun) A formal charge; here, strong criticism."],["Martyrdom","(Noun) Self-destruction treated as moral ideal."],["Devotion","(Noun) Deep love and commitment."],["Collapse","(Verb) To break down physically or emotionally."],["Unpaid","(Adjective) Done without payment."],["Inspirational","(Adjective) Motivating admiration; often overused in media."],["Boundary","(Noun) A limit protecting one’s well-being."],["Peer group","(Noun) People of similar status who share experiences."],["Noble","(Adjective) Morally admirable; can flatter harmful endurance."]],
